SCRIPT_DIR = Path(__file__).resolve().parent


def locate_repository() -> Path:
    candidates = []
    for base in (Path.cwd().resolve(), SCRIPT_DIR):
        candidates.extend((base, base / "kalshi-qss-bot"))
        for parent in base.parents:
            candidates.extend((parent, parent / "kalshi-qss-bot"))
    seen = set()
    for candidate in candidates:
        candidate = candidate.resolve()
        if candidate in seen:
            continue
        seen.add(candidate)
        source = candidate / "qseries_v2" / "oracle_research_response" / "oracle_research_response_evidence_read_invocation_attestation_consumption_continuation_gate.py"
        if source.is_file():
            return candidate
    raise SystemExit("[ERROR] Could not locate repository with actual ORR-015 module.")


